sp_widget.client_script:
api.controller = function($window, cabrillo) {

    var c = this;


    c.menuOpen = false;
    c.userMenuOpen = false;
    c.userPickerOpen = false;
    c.userSearch = '';
    c.userResults = [];
    c.userSearching = false;
    c.notificationOpen = false;


    /* =========================================
       DETECT REAL NOW MOBILE APP
    ========================================= */

    c.isNative = false;

    try {

        c.isNative =
            cabrillo &&
            cabrillo.isNative &&
            cabrillo.isNative();

    }
    catch (e) {

        c.isNative = false;

    }


    c.isAppView =
        c.isNative ||
        (
            c.data &&
            c.data.isMobileApp === true
        );


    /* =========================================
       BUILD CAMPUSMATCH URL
    ========================================= */

    c.buildCampusMatchUrl = function(pageId) {

        var target =
            $window.location.origin +
            '/campusmatch?id=' +
            pageId;


        if (c.isAppView) {

            target +=
                '&cm_mobile=1';

        }


        return target;

    };


    /* =========================================
       BUILD NOTIFICATION TARGET URL
    ========================================= */

    c.buildNotificationUrl = function(targetUrl) {

        targetUrl =
            targetUrl ||
            '?id=campusmatch_dashboard';


        var target = '';


        if (
            targetUrl.indexOf('http://') === 0 ||
            targetUrl.indexOf('https://') === 0
        ) {

            target = targetUrl;

        }
        else if (
            targetUrl.charAt(0) === '?'
        ) {

            target =
                $window.location.origin +
                '/campusmatch' +
                targetUrl;

        }
        else if (
            targetUrl.charAt(0) === '/'
        ) {

            target =
                $window.location.origin +
                targetUrl;

        }
        else {

            target =
                $window.location.origin +
                '/campusmatch?' +
                targetUrl;

        }


        if (
            c.isAppView &&
            target.indexOf('cm_mobile=1') === -1
        ) {

            target +=
                (
                    target.indexOf('?') !== -1
                        ? '&'
                        : '?'
                ) +
                'cm_mobile=1';

        }


        return target;

    };


    /* =========================================
       WEBSITE MENU
    ========================================= */

    c.toggleMenu = function() {

        c.menuOpen =
            !c.menuOpen;

        c.notificationOpen =
            false;

        c.userMenuOpen =
            false;

    };


    c.closeMenu = function() {

        c.menuOpen = false;

    };


    /* =========================================
       NOTIFICATION MENU
    ========================================= */

    c.toggleNotifications = function($event) {

        if ($event) {

            $event.preventDefault();
            $event.stopPropagation();

        }


        c.notificationOpen =
            !c.notificationOpen;


        c.menuOpen =
            false;

        c.userMenuOpen =
            false;

    };


    /* =========================================
       OPEN NOTIFICATION
    ========================================= */

    c.openNotification = function(
        $event,
        notification
    ) {

        if ($event) {

            $event.preventDefault();
            $event.stopPropagation();

        }


        if (
            !notification ||
            !notification.sys_id
        ) {

            return;

        }


        var target =
            c.buildNotificationUrl(
                notification.targetUrl
            );


        if (
            !notification.isRead
        ) {

            notification.isRead =
                true;


            if (
                c.data.notificationUnreadCount >
                0
            ) {

                c.data.notificationUnreadCount--;

            }

        }


        c.notificationOpen =
            false;


        c.server.get({

            action:
                'mark_notification_read',

            notification_id:
                notification.sys_id

        }).then(

            function() {

                $window.location.href =
                    target;

            },

            function() {

                $window.location.href =
                    target;

            }

        );

    };


    /* =========================================
       APP USER MENU
    ========================================= */

    c.toggleUserMenu = function($event) {

        if ($event) {

            $event.preventDefault();
            $event.stopPropagation();

        }


        c.userMenuOpen =
            !c.userMenuOpen;


        c.notificationOpen =
            false;

    };


    /* =========================================
       SWITCH USER
    ========================================= */

    c.showUserPicker = function($event) {

        if ($event) {

            $event.preventDefault();
            $event.stopPropagation();

        }


        c.userMenuOpen = false;

        c.notificationOpen = false;


        var campusMatchTarget =
            c.buildCampusMatchUrl(
                'campusmatch_home_hero'
            );


        var target =
            $window.location.origin +
            '/impersonate_dialog.do' +
            '?sysparm_target=' +
            encodeURIComponent(
                campusMatchTarget
            );


        $window.location.href =
            target;

    };


    /* =========================================
       END IMPERSONATION
    ========================================= */

    c.endImpersonation = function($event) {

        if ($event) {

            $event.preventDefault();
            $event.stopPropagation();

        }


        c.userMenuOpen = false;

        c.notificationOpen = false;


        var campusMatchTarget =
            c.buildCampusMatchUrl(
                'campusmatch_home_hero'
            );


        var target =
            $window.location.origin +
            '/impersonate_dialog.do' +
            '?sysparm_target=' +
            encodeURIComponent(
                campusMatchTarget
            );


        $window.location.href =
            target;

    };


    /* =========================================
       RELOAD CAMPUSMATCH
    ========================================= */

    c.reloadCampusMatch = function() {

        var target =
            c.buildCampusMatchUrl(
                'campusmatch_home_hero'
            );


        $window.location.replace(
            target
        );

    };


    /* =========================================
       HARD PORTAL NAVIGATION
    ========================================= */

    c.goToPage = function(
        $event,
        pageId
    ) {

        if ($event) {

            $event.preventDefault();
            $event.stopPropagation();

        }


        c.menuOpen = false;

        c.userMenuOpen = false;

        c.notificationOpen = false;


        var target =
            c.buildCampusMatchUrl(
                pageId
            );


        $window.location.replace(
            target
        );

    };

};

sp_widget.css:
/* =====================================================
   CAMPUSMATCH HEADER
   WEBSITE + NOW MOBILE APP
===================================================== */


/* =====================================================
   COMMON FULL-BLEED HEADER BASE
===================================================== */

.cm-navbar,
.cm-app-header {
  position: relative;
  z-index: 1000;

  width: 100vw !important;
  max-width: 100vw !important;

  margin-left: calc(50% - 50vw) !important;
  margin-right: calc(50% - 50vw) !important;

  margin-top: 0 !important;
  margin-bottom: 0 !important;

  background: #FBF8EF !important;

  border-bottom: 1px solid #D2DED8;

  box-sizing: border-box !important;
}


/* =====================================================
   COVER TOP WHITE STRIP
===================================================== */

.cm-navbar::before,
.cm-app-header::before {
  content: "";

  position: absolute;

  left: 50%;
  top: -40px;

  width: 100vw;
  height: 40px;

  transform: translateX(-50%);

  background: #FBF8EF;

  pointer-events: none;

  z-index: -1;
}


/* =====================================================
   WEBSITE HEADER INNER CONTAINER
===================================================== */

.cm-nav-container {
  width: 100%;
  max-width: 100%;

  min-height: 64px;

  display: flex;
  align-items: center;

  padding: 6px 28px;

  box-sizing: border-box;
}


/* =====================================================
   WEBSITE LOGO
===================================================== */

.cm-brand {
  display: flex;
  align-items: center;

  flex-shrink: 0;

  text-decoration: none !important;
}


.cm-brand-logo {
  display: block;

  width: 158px;
  max-width: 158px;

  height: auto;

  object-fit: contain;
}


/* =====================================================
   DESKTOP NAVIGATION
===================================================== */

.cm-desktop-nav {
  display: flex;
  align-items: center;

  gap: 28px;

  margin-left: auto;
}


.cm-desktop-nav a {
  color: #163D39 !important;

  font-family:
    'DM Sans',
    'Segoe UI',
    Arial,
    sans-serif;

  font-size: 15px;
  font-weight: 600;

  text-decoration: none !important;

  white-space: nowrap;

  cursor: pointer;

  transition: color 0.2s ease;
}


.cm-desktop-nav a:hover {
  color: #2F766A !important;
}


/* =====================================================
   DESKTOP USER
===================================================== */

.cm-user-area {
  display: flex;
  align-items: center;

  margin-left: 24px;
}


.cm-user-circle {
  width: 42px;
  height: 42px;

  min-width: 42px;

  display: flex;
  align-items: center;
  justify-content: center;

  flex-shrink: 0;

  border-radius: 50%;

  border: 1px solid #D2DED8;

  background: #EDF5E9;

  color: #15564B;

  font-family:
    'DM Sans',
    'Segoe UI',
    Arial,
    sans-serif;

  font-size: 14px;
  font-weight: 800;

  line-height: 1;

  box-sizing: border-box;
}


/* =====================================================
   HAMBURGER BUTTON
===================================================== */

.cm-menu-button {
  display: none;

  width: 44px;
  height: 44px;

  margin-left: auto;

  padding: 10px;

  border: 0;
  border-radius: 10px;

  background: transparent;

  cursor: pointer;

  flex-direction: column;
  align-items: center;
  justify-content: center;

  gap: 5px;
}


.cm-menu-button span {
  display: block;

  width: 23px;
  height: 2px;

  background: #15564B;

  border-radius: 10px;

  transition:
    transform 0.2s ease,
    opacity 0.2s ease;
}


/* =====================================================
   HAMBURGER → X
===================================================== */

.cm-menu-button.active span:nth-child(1) {
  transform: translateY(7px) rotate(45deg);
}


.cm-menu-button.active span:nth-child(2) {
  opacity: 0;
}


.cm-menu-button.active span:nth-child(3) {
  transform: translateY(-7px) rotate(-45deg);
}


/* =====================================================
   WEBSITE MOBILE / TABLET MENU
===================================================== */

.cm-mobile-menu {
  display: none;

  width: 100%;
  max-width: 100%;

  padding: 8px 20px 20px;

  background: #FBF8EF;

  border-top: 1px solid #E0E8E3;

  box-sizing: border-box;
}


.cm-mobile-menu.open {
  display: flex;

  flex-direction: column;
}


.cm-mobile-menu > a {
  width: 100%;

  padding: 14px 4px;

  color: #163D39 !important;

  font-family:
    'DM Sans',
    'Segoe UI',
    Arial,
    sans-serif;

  font-size: 15px;
  font-weight: 600;

  text-decoration: none !important;

  border-bottom: 1px solid #E7ECE8;

  box-sizing: border-box;
}


/* =====================================================
   WEBSITE MOBILE USER
===================================================== */

.cm-mobile-user {
  display: flex;
  align-items: center;

  gap: 12px;

  padding-top: 18px;
}


.cm-mobile-user-details {
  display: flex;
  flex-direction: column;

  gap: 2px;
}


.cm-mobile-user-name {
  color: #163D39;

  font-family:
    'DM Sans',
    'Segoe UI',
    Arial,
    sans-serif;

  font-size: 14px;
  font-weight: 700;
}


.cm-mobile-user-role {
  color: #66827D;

  font-family:
    'DM Sans',
    'Segoe UI',
    Arial,
    sans-serif;

  font-size: 12px;
  font-weight: 500;
}


/* =====================================================
   DESKTOP / LAPTOP WEBSITE
===================================================== */

@media (min-width: 901px) {

  .cm-desktop-nav {
    display: flex !important;
  }


  .cm-user-area {
    display: flex !important;
  }


  .cm-menu-button {
    display: none !important;
  }


  .cm-mobile-menu {
    display: none !important;
  }

}


/* =====================================================
   TABLET + MOBILE WEBSITE
===================================================== */

@media (max-width: 900px) {

  .cm-nav-container {
    min-height: 72px;

    padding: 10px 18px;
  }


  .cm-brand {
    margin-right: auto;
  }


  .cm-brand-logo {
    width: 150px;
    max-width: 150px;
  }


  .cm-desktop-nav {
    display: none !important;
  }


  .cm-user-area {
    display: none !important;
  }


  .cm-menu-button {
    display: flex !important;

    margin-left: 4px;
  }


  .cm-mobile-menu {
    display: none !important;
  }


  .cm-mobile-menu.open {
    display: flex !important;

    flex-direction: column;
  }

}


/* =====================================================
   VERY SMALL WEBSITE SCREENS
===================================================== */

@media (max-width: 480px) {

  .cm-nav-container {
    padding-left: 14px;
    padding-right: 14px;
  }


  .cm-brand-logo {
    width: 142px;
    max-width: 142px;
  }

}


/* =====================================================
   NOW MOBILE APP HEADER
===================================================== */

.cm-app-header {
  min-height: 76px;

  display: flex;
  align-items: center;
  justify-content: space-between;

  gap: 16px;

  padding: 12px 18px;

  box-sizing: border-box;
}


/* =====================================================
   NOW MOBILE APP LOGO
===================================================== */

.cm-app-brand {
  display: flex;
  align-items: center;

  flex: 1 1 auto;

  min-width: 0;

  text-decoration: none !important;
}


.cm-app-brand-logo {
  display: block;

  width: 158px;
  max-width: 158px;

  height: auto;

  object-fit: contain;
}


/* =====================================================
   APP USER WRAPPER
===================================================== */

.cm-app-user-wrapper {
  position: relative;

  display: flex;
  align-items: center;

  flex-shrink: 0;
}


/* =====================================================
   NOW MOBILE APP USER CIRCLE
===================================================== */

.cm-app-user-circle {
  width: 42px;
  height: 42px;

  min-width: 42px;

  display: flex;
  align-items: center;
  justify-content: center;

  flex-shrink: 0;

  border-radius: 50%;

  border: 1px solid #D2DED8;

  background: #EDF5E9;

  color: #15564B;

  font-family:
    'DM Sans',
    'Segoe UI',
    Arial,
    sans-serif;

  font-size: 14px;
  font-weight: 800;

  line-height: 1;

  box-sizing: border-box;
}


/* =====================================================
   SMALL MOBILE APP
===================================================== */

@media (max-width: 480px) {

  .cm-app-header {
    min-height: 72px;

    padding: 10px 14px;
  }


  .cm-app-brand-logo {
    width: 142px;
    max-width: 142px;
  }


  .cm-app-user-circle {
    width: 40px;
    height: 40px;

    min-width: 40px;

    font-size: 13px;
  }

}


/* =====================================================
   VERY SMALL MOBILE APP
===================================================== */

@media (max-width: 390px) {

  .cm-app-header {
    padding-left: 12px;
    padding-right: 12px;
  }


  .cm-app-brand-logo {
    width: 136px;
    max-width: 136px;
  }


  .cm-app-user-circle {
    width: 38px;
    height: 38px;

    min-width: 38px;

    font-size: 12px;
  }

}


/* =====================================================
   NOTIFICATION WRAPPER
===================================================== */

.cm-notification-wrap {
  position: relative;

  margin-left: 16px;

  flex-shrink: 0;

  font-family:
    'DM Sans',
    'Segoe UI',
    Arial,
    sans-serif;
}


/* =====================================================
   NOTIFICATION BUTTON
===================================================== */

.cm-notification-button {
  position: relative;

  width: 42px;
  height: 42px;

  min-width: 42px;

  display: flex;
  align-items: center;
  justify-content: center;

  padding: 0;

  border: 1px solid #D2DED8;
  border-radius: 50%;

  background: #FFFFFF;

  color: #15564B;

  cursor: pointer;

  box-sizing: border-box;

  transition:
    background 0.2s ease,
    border-color 0.2s ease,
    transform 0.2s ease;
}


.cm-notification-button:hover {
  background: #EDF5E9;

  border-color: #B7CBC1;
}


.cm-notification-button:active {
  transform: scale(0.96);
}


.cm-notification-button svg {
  width: 19px;
  height: 19px;

  display: block;
}


/* =====================================================
   ORANGE UNREAD INDICATOR
===================================================== */

.cm-notification-indicator {
  position: absolute;

  top: 3px;
  right: 3px;

  width: 10px;
  height: 10px;

  display: block;

  border: 2px solid #FBF8EF;
  border-radius: 50%;

  background: #F4A261;

  box-sizing: border-box;

  pointer-events: none;
}


/* =====================================================
   NOTIFICATION PANEL
===================================================== */

.cm-notification-panel {
  position: absolute;

  top: calc(100% + 10px);
  right: 0;

  width: 355px;
  max-height: 430px;

  overflow: hidden;

  border: 1px solid #D2DED8;
  border-radius: 18px;

  background: #FFFFFF;

  box-shadow:
    0 18px 45px
    rgba(16, 78, 69, 0.15);

  z-index: 5000;

  box-sizing: border-box;
}


.cm-notification-panel-header {
  padding: 15px 16px;

  border-bottom: 1px solid #E6ECE8;

  background: #FFFFFF;
}


.cm-notification-panel-header > div {
  display: flex;
  align-items: center;
  justify-content: space-between;

  gap: 12px;
}


.cm-notification-panel-header strong {
  color: #104E45;

  font-size: 14px;
  font-weight: 800;
}


.cm-notification-panel-header span {
  color: #66827D;

  font-size: 10px;
  font-weight: 600;
}


/* =====================================================
   NOTIFICATION LIST
===================================================== */

.cm-notification-list {
  max-height: 365px;

  overflow-y: auto;
}


.cm-notification-row {
  width: 100%;

  padding: 14px 15px;

  display: grid;

  grid-template-columns:
    9px minmax(0, 1fr);

  align-items: flex-start;

  gap: 11px;

  border: 0;
  border-bottom: 1px solid #EDF2EE;

  background: #FFFFFF;

  font-family: inherit;

  text-align: left;

  cursor: pointer;

  box-sizing: border-box;

  transition:
    background 0.2s ease;
}


.cm-notification-row:last-child {
  border-bottom: 0;
}


.cm-notification-row:hover {
  background: #F8FAF6;
}


.cm-notification-row.unread {
  background: #F2F8EF;
}


/* =====================================================
   NOTIFICATION ROW DOT
===================================================== */

.cm-notification-dot {
  width: 8px;
  height: 8px;

  margin-top: 5px;

  display: block;

  border-radius: 50%;

  background: #D2DED8;
}


.cm-notification-row.unread
.cm-notification-dot {
  background: #249D78;
}


/* =====================================================
   NOTIFICATION CONTENT
===================================================== */

.cm-notification-content {
  min-width: 0;

  display: flex;
  flex-direction: column;

  gap: 4px;
}


.cm-notification-content strong {
  color: #102E34;

  font-size: 12px;
  font-weight: 800;

  line-height: 1.35;
}


.cm-notification-message {
  display: -webkit-box;

  overflow: hidden;

  color: #506267;

  font-size: 10px;
  font-weight: 500;

  line-height: 1.45;

  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}


.cm-notification-content small {
  color: #879397;

  font-size: 9px;
  font-weight: 500;
}


/* =====================================================
   EMPTY NOTIFICATION STATE
===================================================== */

.cm-notification-empty {
  padding: 30px 18px;

  color: #718185;

  font-size: 11px;
  font-weight: 500;

  text-align: center;
}


/* =====================================================
   TABLET + MOBILE WEBSITE NOTIFICATIONS
===================================================== */

@media (max-width: 900px) {

  .cm-notification-wrap {
    margin-left: 8px;
    margin-right: 4px;
  }


  .cm-notification-panel {
    position: fixed;

    top: 76px;
    right: 14px;

    width: calc(100vw - 28px);

    max-width: 380px;

    max-height: calc(100vh - 100px);
  }


  .cm-notification-list {
    max-height: calc(100vh - 165px);
  }

}


/* =====================================================
   NOW MOBILE APP NOTIFICATIONS
===================================================== */

.cm-app-notification-wrap {
  margin-left: 4px;
  margin-right: 4px;
}


.cm-app-notification-panel {
  position: fixed;

  top: 82px;
  right: 14px;

  width: calc(100vw - 28px);

  max-width: 380px;

  max-height: calc(100vh - 105px);
}


/* =====================================================
   SMALL SCREEN NOTIFICATIONS
===================================================== */

@media (max-width: 480px) {

  .cm-notification-button {
    width: 40px;
    height: 40px;

    min-width: 40px;
  }


  .cm-notification-button svg {
    width: 18px;
    height: 18px;
  }


  .cm-notification-indicator {
    top: 3px;
    right: 3px;

    width: 9px;
    height: 9px;
  }


  .cm-notification-panel,
  .cm-app-notification-panel {
    top: 74px;
    right: 10px;

    width: calc(100vw - 20px);

    border-radius: 16px;
  }

}


/* =====================================================
   VERY SMALL SCREEN NOTIFICATIONS
===================================================== */

@media (max-width: 390px) {

  .cm-notification-button {
    width: 38px;
    height: 38px;

    min-width: 38px;
  }


  .cm-notification-indicator {
    width: 9px;
    height: 9px;
  }

}

sp_widget.script:
(function() {


    /* =========================================
       CONSTANTS
    ========================================= */

    var NOTIFICATION_TABLE =
        'x_snc_campusmatch_campusmatch_notification';



    /* =========================================
       DEFAULT RESPONSE DATA
    ========================================= */

    data.success = false;

    data.message = '';

    data.users = [];

    data.notifications = [];

    data.notificationUnreadCount = 0;



    /* =========================================
       SERVER ACTIONS
    ========================================= */

    if (
        input &&
        input.action
    ) {


        /* =====================================
           MARK NOTIFICATION AS READ
        ===================================== */

        if (
            input.action ==
            'mark_notification_read'
        ) {

            var notificationId =
                (
                    input.notification_id ||
                    ''
                )
                .toString()
                .trim();


            if (!notificationId) {

                data.message =
                    'Notification was not provided.';

                return;

            }


            if (
                gs.getUserID() ==
                'guest'
            ) {

                data.message =
                    'Login required.';

                return;

            }


            var notificationGR =
                new GlideRecord(
                    NOTIFICATION_TABLE
                );


            notificationGR.addQuery(
                'sys_id',
                notificationId
            );


            /*
             * User can only update
             * their own notification.
             */

            notificationGR.addQuery(
                'recipient',
                gs.getUserID()
            );


            notificationGR.setLimit(
                1
            );


            notificationGR.query();


            if (
                notificationGR.next()
            ) {

                /*
                 * IMPORTANT:
                 * Actual field name is "read"
                 */

                notificationGR.setValue(
                    'read',
                    true
                );


                if (
                    notificationGR.isValidField(
                        'read_on'
                    )
                ) {

                    notificationGR.setValue(
                        'read_on',
                        new GlideDateTime()
                            .getValue()
                    );

                }


                notificationGR.update();


                data.success =
                    true;


                data.message =
                    'Notification marked as read.';

            }
            else {

                data.message =
                    'Notification was not found.';

            }


            return;

        }



        /* =====================================
           SEARCH USERS
        ===================================== */

        if (
            input.action ==
            'search_users'
        ) {


            if (
                !gs.hasRole(
                    'admin'
                )
            ) {

                data.message =
                    'Administrator access required.';

                return;

            }


            var query =
                (
                    input.query ||
                    ''
                )
                .toString()
                .trim();


            if (
                query.length < 2
            ) {

                return;

            }


            var userGR =
                new GlideRecord(
                    'sys_user'
                );


            userGR.addActiveQuery();


            var userQuery =
                userGR.addQuery(
                    'name',
                    'CONTAINS',
                    query
                );


            userQuery.addOrCondition(
                'user_name',
                'CONTAINS',
                query
            );


            userQuery.addOrCondition(
                'first_name',
                'CONTAINS',
                query
            );


            userQuery.addOrCondition(
                'last_name',
                'CONTAINS',
                query
            );


            userGR.orderBy(
                'name'
            );


            userGR.setLimit(
                10
            );


            userGR.query();


            while (
                userGR.next()
            ) {

                var name =
                    userGR.getDisplayValue();


                var initials =
                    '';


                if (name) {

                    var parts =
                        name
                            .trim()
                            .split(
                                /\s+/
                            );


                    if (
                        parts.length === 1
                    ) {

                        initials =
                            parts[0]
                                .substring(
                                    0,
                                    2
                                )
                                .toUpperCase();

                    }
                    else {

                        initials =
                            (
                                parts[0]
                                    .charAt(
                                        0
                                    ) +

                                parts[
                                    parts.length -
                                    1
                                ]
                                    .charAt(
                                        0
                                    )
                            )
                            .toUpperCase();

                    }

                }


                data.users.push({

                    sys_id:
                        userGR
                            .getUniqueValue(),

                    name:
                        name,

                    user_name:
                        userGR.getValue(
                            'user_name'
                        ),

                    initials:
                        initials

                });

            }


            data.success =
                true;


            return;

        }



        /* =====================================
           IMPERSONATE USER
        ===================================== */

        if (
            input.action ==
            'impersonate'
        ) {


            if (
                !gs.hasRole(
                    'admin'
                )
            ) {

                data.message =
                    'Administrator access required.';

                return;

            }


            var targetUser =
                (
                    input.user_sys_id ||
                    ''
                )
                .toString();


            if (!targetUser) {

                data.message =
                    'User was not provided.';

                return;

            }


            try {

                var impersonator =
                    new GlideImpersonate();


                if (
                    !impersonator
                        .canImpersonate(
                            targetUser
                        )
                ) {

                    data.message =
                        'This user cannot be impersonated.';

                    return;

                }


                impersonator.impersonate(
                    targetUser
                );


                data.success =
                    true;


                data.message =
                    'Impersonation started.';


                return;

            }
            catch (
                impersonateError
            ) {

                data.message =
                    impersonateError.message;


                return;

            }

        }



        /* =====================================
           END IMPERSONATION
        ===================================== */

        if (
            input.action ==
            'end_impersonation'
        ) {

            try {

                if (
                    !gs.getSession()
                        .isImpersonating()
                ) {

                    data.message =
                        'No impersonation session is active.';

                    return;

                }


                gs.getSession()
                    .onlineUnimpersonate();


                data.success =
                    true;


                data.message =
                    'Impersonation ended.';


                return;

            }
            catch (
                endError
            ) {

                data.message =
                    endError.message;


                return;

            }

        }

    }



    /* =========================================
       LOGIN STATE
    ========================================= */

    data.loggedIn =
        gs.getUserID() !=
        'guest';



    /* =========================================
       MOBILE APP DETECTION
    ========================================= */

    data.isMobileApp =
        $sp.getParameter(
            'cm_mobile'
        ) == '1';



    /* =========================================
       USER DETAILS
    ========================================= */

    data.userName =
        gs.getUserDisplayName();


    data.initials =
        '';


    if (
        data.userName
    ) {

        var userNameParts =
            data.userName
                .trim()
                .split(
                    /\s+/
                );


        if (
            userNameParts.length ===
            1
        ) {

            data.initials =
                userNameParts[0]
                    .substring(
                        0,
                        2
                    )
                    .toUpperCase();

        }
        else {

            data.initials =
                (
                    userNameParts[0]
                        .charAt(
                            0
                        ) +

                    userNameParts[
                        userNameParts.length -
                        1
                    ]
                        .charAt(
                            0
                        )
                )
                .toUpperCase();

        }

    }



    /* =========================================
       STAFF ACCESS
    ========================================= */

    var access =
        new CampusMatchAccess();


    data.isStaff =
        access.isStaff();



    /* =========================================
       ADMIN ACCESS
    ========================================= */

    /*
     * Used by the Header HTML to show
     * the Deadlines button only to admins.
     */

    data.isAdmin =
        gs.hasRole(
            'admin'
        );



    /* =========================================
       STUDENT NOTIFICATIONS
    ========================================= */

    if (
        data.loggedIn &&
        !data.isStaff
    ) {


        /* =====================================
           UNREAD COUNT
        ===================================== */

        var unreadGR =
            new GlideAggregate(
                NOTIFICATION_TABLE
            );


        unreadGR.addQuery(
            'recipient',
            gs.getUserID()
        );


        unreadGR.addQuery(
            'audience',
            'student'
        );


        /*
         * IMPORTANT:
         * Actual field name is "read"
         */

        unreadGR.addQuery(
            'read',
            false
        );


        unreadGR.addAggregate(
            'COUNT'
        );


        unreadGR.query();


        if (
            unreadGR.next()
        ) {

            data.notificationUnreadCount =
                parseInt(
                    unreadGR
                        .getAggregate(
                            'COUNT'
                        ),
                    10
                ) ||
                0;

        }



        /* =====================================
           LOAD RECENT NOTIFICATIONS
        ===================================== */

        var recentNotificationGR =
            new GlideRecord(
                NOTIFICATION_TABLE
            );


        recentNotificationGR.addQuery(
            'recipient',
            gs.getUserID()
        );


        recentNotificationGR.addQuery(
            'audience',
            'student'
        );


        recentNotificationGR.orderByDesc(
            'sys_created_on'
        );


        recentNotificationGR.setLimit(
            10
        );


        recentNotificationGR.query();


        while (
            recentNotificationGR.next()
        ) {

            data.notifications.push({

                sys_id:
                    recentNotificationGR
                        .getUniqueValue(),

                title:
                    recentNotificationGR
                        .getValue(
                            'title'
                        ) ||
                    'CampusMatch update',

                message:
                    recentNotificationGR
                        .getValue(
                            'message'
                        ) ||
                    '',

                targetUrl:
                    recentNotificationGR
                        .getValue(
                            'target_url'
                        ) ||
                    '?id=campusmatch_dashboard',

                notificationType:
                    recentNotificationGR
                        .getValue(
                            'notification_type'
                        ) ||
                    '',

                emailSubject:
                    recentNotificationGR
                        .getValue(
                            'email_subject'
                        ) ||
                    '',


                /*
                 * IMPORTANT:
                 * Actual field name is "read"
                 */

                isRead:
                    recentNotificationGR
                        .getValue(
                            'read'
                        ) ==
                    '1',

                created:
                    recentNotificationGR
                        .getDisplayValue(
                            'sys_created_on'
                        ) ||
                    ''

            });

        }

    }



    /* =========================================
       IMPERSONATION STATUS
    ========================================= */

    data.isImpersonating =
        false;


    try {

        data.isImpersonating =
            new GlideImpersonate()
                .isImpersonating();

    }
    catch (e) {

        data.isImpersonating =
            gs.getSession()
                .isImpersonating();

    }



    /* =========================================
       ADMIN IMPERSONATION ACCESS
    ========================================= */

    data.canImpersonate =
        gs.hasRole(
            'admin'
        ) &&
        !data.isImpersonating;



})();
